  VALUES 
    (184::BIGINT, 'Buena nota. Si usted no sabe nadar la recomiendo. Sin embargo, normalmente deja a sus asistentes dando la clase, por lo que tampoco está muy comprometida.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2026-07-02T00:00:00+00:00'::TIMESTAMPTZ, '21727732eae11f6821f44e35fbfead8e4ecb60c5ac980bccb73fb567121b0e9d'::TEXT, ARRAY[492]::BIGINT[]),
    (184::BIGINT, 'Buena nota la profe, pero generalmente deja a los estudiantes dando la clase, lo que hizo que mi aprendizaje se viera obstruido.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2025-12-08T00:00:00+00:00'::TIMESTAMPTZ, '4b86f6e473fc1a13ea0375042496e6bb0495ac4f73e2d8bf2c2789dc4431ac37'::TEXT, ARRAY[492]::BIGINT[]),
    (184::BIGINT, 'Es una corrupta'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-27T00:00:00+00:00'::TIMESTAMPTZ, '3b0e6b0bcf41636a3fd162f3a28cb7a0f079dc3a5eb74b76b9237b749966542e'::TEXT, ARRAY[492]::BIGINT[]),
    (184::BIGINT, 'Es la profesora perfecta para natación, sea que usted nada muy bien o no sabe nadar en lo absoluto. Lo guía a uno hasta que aprenda, y sabe señalar los puntos de mejora. Además, cae bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa']::TEXT[], '2025-05-05T00:00:00+00:00'::TIMESTAMPTZ, '185e5d3a52d4f632a4359b09007d0b658230d5dfbd462f793b54089d79cdbf79'::TEXT, ARRAY[492]::BIGINT[]),
    (184::BIGINT, 'La profe es demasiada linda, el curso se pasa facil y no hay trabajos fuera de clase'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2024-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'c08e995a45be2f0143c007717ae588360da145f118127368c28eafdaaf8d4173'::TEXT, ARRAY[492]::BIGINT[]),
    (184::BIGINT, 'Muy buena profe, también los asistentes. Te ayuda a mejorar la técnica si es que ya sabes nadar y si es de cero, es muy comprensiva. Es una clase para relajarse y disfrutarla.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-10-24T00:00:00+00:00'::TIMESTAMPTZ, '82c52b1b00372ba224e92095036563836fac13965ae35244f0dcb1bef0ac99c7'::TEXT, ARRAY[492]::BIGINT[]),
    (184::BIGINT, 'Argolla con la gente que le cae bien'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-09-19T00:00:00+00:00'::TIMESTAMPTZ, '4567e0c099b985faea08981e9c88a50ec230ad067d9cdbf9d9531ed915a1d4db'::TEXT, ARRAY[492]::BIGINT[]),
    (184::BIGINT, 'La profe es excelente. Divide el grupo según su nivel y apoya mucho al estudiante para que avance. Es un poco estricta con la técnica, pero nada para preocuparse. Sin duda matricularia de nuevo. Si no sabe nadar y quiere aprender la profe es muy comprensiva y ayuda demasiado.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, '8c4e8f879c0732d236691c4eeea2d752b298473d9f42672e3b3daa7b30b7f0b5'::TEXT, ARRAY[492]::BIGINT[]),
    (184::BIGINT, 'Buena profe, es muy paciente y de verdad ayuda para aprender a nadar bien. Las clases son de asistencia obligatoria pero si falta deja reponerla otros días para no perder las horas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Inspirador', 'Brinda apoyo']::TEXT[], '2024-06-05T00:00:00+00:00'::TIMESTAMPTZ, 'ff1433c3cb9dec2c832d6cb2202614913eedc2c115743d132626da38617aaf2f'::TEXT, ARRAY[492]::BIGINT[]),
    (184::BIGINT, 'La profe es buena gente, hace actividades y muy pocas veces dura las 2 horas de la clase. Es un toque estricta pero si necesita faltar puede reponer las clases en otros horarios para no perder el curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-05-28T00:00:00+00:00'::TIMESTAMPTZ, '26dbe6e58bdc0853530b9e0ce6288036374c9caea4feb7f097cabb3f2a6570ee'::TEXT, ARRAY[492]::BIGINT[]),
    (184::BIGINT, 'La profe es un amor y realmente ayuda a que se pueda aprender a nadar si usted no sabe nada, deja reponer las clases que no pueda ir.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-12-15T00:00:00+00:00'::TIMESTAMPTZ, 'e847b10110cb5235ee20d110dcf5bc267b19f079926be19e33d3456e533b3ea8'::TEXT, ARRAY[492]::BIGINT[]),
    (184::BIGINT, 'Pura argolla es esta señora'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-12-01T00:00:00+00:00'::TIMESTAMPTZ, '06f6c0cca4bd91177edaa7c1d187f8dd39f75474203777bdeb4b7e59f8c07c46'::TEXT, ARRAY[492]::BIGINT[]),
    (184::BIGINT, 'La profe es muy buena gente, ofrece ayuda y deja reponer las clases. Si usted no sabe nadar o le da miedo, no le recomendaría con ella porque si es muy estricta y espera mucho de uno; pero en general ella es muy buena.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2023-07-10T00:00:00+00:00'::TIMESTAMPTZ, '3ee60d597a6d8fec725c264d8cba2d93d7abe8d97c0b6f708fdfdae5c7a6603d'::TEXT, ARRAY[492]::BIGINT[]),
    (184::BIGINT, 'Le interesa que usted disfrute la actividad y pase el curso. Si tiene que faltar por algún motivo, le deja reponer clases en otros horarios para que no pierda el curso. Un amor de persona. Totalmente recomendada.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'f44620a1a13124c604b657a157cef037be43e397cd78b29770a1a1c4be63cd92'::TEXT, ARRAY[492]::BIGINT[]),
    (184::BIGINT, 'Solamente estuve con ella 4 semanas porque estaba reemplazando a otra profe, pero si ve que usted no hace los ejercicios bien le ayuda hasta que lo logre. Es buena gente y no es estricta con las ausencias'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-18T00:00:00+00:00'::TIMESTAMPTZ, '730f9ce5d8717c9d6c7479527ae178438ff8ce5d316073b94c91cfd87db1ba48'::TEXT, ARRAY[493]::BIGINT[]),
    (184::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-07T00:00:00+00:00'::TIMESTAMPTZ, '8db32fe2b1f5a3bf58714712882648ed231e6cd6e9f6bbc7d08ecd57dffe50c6'::TEXT, ARRAY[494]::BIGINT[]),
    (184::BIGINT, 'Súper buena profesora, solo hay que ir a clase y hacer el portafolio que básicamente no es nada. Incluso se puede faltar a clase y no baja puntos, solo es cuestión de tener todo al día y cumplir lo que pide.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-11-28T00:00:00+00:00'::TIMESTAMPTZ, '2ebf1782b4c14e28f33eb1740fc50e1a1f2bfa233eb304ca96b8d0239d30cbc7'::TEXT, ARRAY[494]::BIGINT[]),
    (184::BIGINT, 'Es la mejor profesora es super linda y con solo ir a clases y hacer el portafolio se pasa, el portafolio es muy poco lo que se pone semanal'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-25T00:00:00+00:00'::TIMESTAMPTZ, '3d801d9ef8caa515077158947a12474fe2dd745ffed73820f532637da66f481a'::TEXT, ARRAY[494]::BIGINT[]),
    (184::BIGINT, 'Es súper comprensiva. Básicamente el curso se pasa con ir a clases y llevar el portafolio de evidencias en orden. Si no pudo asistir a alguna clase, sólo pide que se agregue la evidencia de que realizó los ejercicios de la semana en el portafolio. Sin duda, súper recomendada'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-20T00:00:00+00:00'::TIMESTAMPTZ, '474eb1bdce01156c79648eb85a87b993652ac3d5f897a4182cc07352c886b58f'::TEXT, ARRAY[494]::BIGINT[]),
    (184::BIGINT, 'Solo vaya a clases y cumpla los portafolios y ez.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2021-07-27T00:00:00+00:00'::TIMESTAMPTZ, 'c6541f5030dd3744cd303d1a478dd882e782c99e8874030c9807b10d9e80427c'::TEXT, ARRAY[494]::BIGINT[]),
    (184::BIGINT, 'Curso relativamente simple, portafolio con evidencias de ejercicios hechos por semana, muy dinámica y en general excelente profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2021-07-27T00:00:00+00:00'::TIMESTAMPTZ, '96d7d0adcfdb0a6bea324526b43cad71271d315d77e9cfe1efacd01a788a9de0'::TEXT, ARRAY[494]::BIGINT[]),
    (184::BIGINT, 'Muy buena profe. Hay que prender cámara o poner evidencias de que se hizo la clase sin cámara. Se lleva un portafolio de comentarios sobre la clase, si tiene un poco de interés se pasa sola. Pd: la profe es empática y por la carga del tec da un par de clases asincrónicas, incluso una de ver una peli'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2021-07-02T00:00:00+00:00'::TIMESTAMPTZ, '51481b449152d96c600b98a03ade3681d81769230e7d142d576902f47bca8479'::TEXT, ARRAY[494]::BIGINT[]),
    (184::BIGINT, 'Buena profesora, si usted es vago y no quiere hacer nada, no meta con ella! Todas las semanas hay que prender la cámara en la clase y hacer los ejercicios o después en el portafolio simular que los hizo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2021-06-26T00:00:00+00:00'::TIMESTAMPTZ, '0279ef68e2e83ce31aef1ccca8e1ddd660c26f0d61746bc609a0bb2bc44bf4be'::TEXT, ARRAY[494]::BIGINT[]),
    (184::BIGINT, 'Se nota que le apasiona lo que hace y lo transmite en sus clases. Hace clases variadas y muy completas. Realmente demuestra interés y se preocupa por el bienestar de los estudiantes.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'c32c0679e7f10c04476b4f02704d0d6c4dc85ae7a1650996115a91bd7bd3b718'::TEXT, ARRAY[494]::BIGINT[]),
    (184::BIGINT, 'Excelente profesora, matricule con ella si tiene la oportunidad'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Clases excelentes']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'cd1b5e2ac4f8114b271851d8d8b1e83e4c48a485a1b6698e4b856b089aa10081'::TEXT, ARRAY[492]::BIGINT[]),
    (184::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Respetado por los estudiantes']::TEXT[], '2020-08-04T00:00:00+00:00'::TIMESTAMPTZ, '25dda1906abad21b7c4d5dc8daad721fb5a83580dc18df7e1f63c9bf856bccdf'::TEXT, ARRAY[492]::BIGINT[]),
    (184::BIGINT, 'Súper Pura Vida, si uno se enferma entiende y deja reponer las clases. La clase no es tan estricta. Sí califica duro el examen entonces sí debería aprender bien la técnica.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-22T00:00:00+00:00'::TIMESTAMPTZ, '9fda108592c611723a7ca9904ffa4d4bb3bee09d2cb7eced48d108a3ed0ecd7f'::TEXT, ARRAY[492]::BIGINT[]),
