    (184::BIGINT, 'La profe es super buena gente y lo motiva a uno a mejorar. PD: No metan natación, a pesar de que la piscina es temperada, Cartago es demasiado frio :('::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo']::TEXT[], '2019-06-08T00:00:00+00:00'::TIMESTAMPTZ, '8e31b5112ed753dd4750e0ead7811a6c8285c6c501f61559e7cd23694f967f0d'::TEXT, ARRAY[492]::BIGINT[]),
