    (184::BIGINT, 'Muy buena persona y profesora, recomendada'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-17T00:00:00+00:00'::TIMESTAMPTZ, '4c7bf7c96e35509bd75b44bb7bd06c17fb64f141032a87643ed855df007dd511'::TEXT, ARRAY[492]::BIGINT[]),
    (184::BIGINT, 'Separa en subgrupos dependiendo de cuanto sabe nadar cada uno (principiantes, intermedios y avanzados). Además es bellísima persona. Muy recomendada.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, '42acc5eeca05b96772d83254671aedb6979517178f747e4dba38d5bdbe9cb5cf'::TEXT, ARRAY[492]::BIGINT[]),
    (184::BIGINT, 'Es super linda'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'd0ce4154f841db857bbe2f32306bbb05a92543c11fb6ff2fc2eb41151509dc17'::TEXT, ARRAY[492]::BIGINT[]),
    (184::BIGINT, 'La profe es buena gente y es la más fácil para natación que conozco'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'c6cfd1192c951fd600e709b821ba669af561797a1f545890c34ff84bb233259e'::TEXT, ARRAY[492]::BIGINT[]),
    (184::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-10T00:00:00+00:00'::TIMESTAMPTZ, '6035c77ae5a9c05dfdcddca5d4fc3790b066ca8b95dd62b6822efcb66d2826b7'::TEXT, ARRAY[492]::BIGINT[]),
    (184::BIGINT, 'La profe es super buenta nota, crea un clima de confianza en la clase que hace que usted se sienta preparado para nadar, uno aprende un monton con ella y las clases se pasan rapido, la recomiendo un monton!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-02-02T00:00:00+00:00'::TIMESTAMPTZ, 'c2f7c1ba5b3166d87f95a3a0d58007373a46bf64504f06d84162b711fb6fc5a9'::TEXT, ARRAY[492]::BIGINT[]),
    (184::BIGINT, 'Una profesora muy buena gente y exigente, pero así como exige, da. Te motiva a seguir y mejorar y te presiona para que dés lo mejor de vos sin llegar a romperte. Ud sale nadando aunque sea de perrito, pero sale nadando.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-02-01T00:00:00+00:00'::TIMESTAMPTZ, '23922b6ebcad04aca3dd9bcbda7a6bb001802282849590fdfebd89a741fa6a43'::TEXT, ARRAY[492]::BIGINT[]),
    (184::BIGINT, 'Ojalá la profe Liz diera clases en la escuela de física o mante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-23T00:00:00+00:00'::TIMESTAMPTZ, '9bd8e38922bfc823265e50213193cc5465a8df054bde24037cd9ca78e19517c4'::TEXT, ARRAY[492]::BIGINT[]),
    (184::BIGINT, 'Súper linda persona. Yo no sabía nadar nada y, si bien no salí con una técnica excelente, al menos ya se algo. El examen es fácil. Si ella ve que usted muestra interés por aprender a nadar, de fijo pasa con una buena nota.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'b64fa61adb7cccbc603c7f0fbeba9b33223e50ef8457a1c9c6ffd847c2a7b619'::TEXT, ARRAY[492]::BIGINT[]),
    (184::BIGINT, 'Es la entrenadora del equipo por lo tanto exige un poco más una buena ejecución de la técnica de nado. Sin embargo el curso no es pesado y ella es demasiado pura vida'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'c1e055c0327c8a9bad2033d8ac117964e32f2d83ee7d3a61782c05475d80b354'::TEXT, ARRAY[492]::BIGINT[]),
    (184::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, '36c3a8f1c056a39a759bfc0bd8ef2a61fa53ae90624ace654ce8baed44bfb1b6'::TEXT, ARRAY[492]::BIGINT[]),
    (184::BIGINT, 'Si sabe nadar meta con ella, sino póngale porque se ahoga.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-05-31T00:00:00+00:00'::TIMESTAMPTZ, 'b335f1dc988f67b4080b9c70b3185efa2e39b4536a1e1b41e124b6a2e2dfe3c6'::TEXT, ARRAY[492]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
